using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00008 : MinimalApiTestBase
    {
        private Regex producesRegex = new Regex(@"Produces\(\d+, typeof\(\w+\)\)");
        private Regex typeOfRegex = new Regex(@"typeof\((\w+)\)");
        
        [TestMethod]
        public void Each_Ok_Produce_Response_Type_Have_To_Be_A_Custom_Response_Type()
        {
            var wrongResponseObjects = (from mapStatement in MapStatements
                                           let producesMatches = producesRegex.Matches(mapStatement.SyntaxTree)
                                           from match in producesMatches
                                           let type = typeOfRegex.Match(match.Value)
                                           where type.Groups[1].Value.DoesNotContain("Response")
                                           select new
                                           {
                                               Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FilePath:  {mapStatement.FilePath}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Syntax:    

{mapStatement.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{mapStatement.SyntaxTree.Replace(type.Value, "typeof(MyCustomResponse)").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(wrongResponseObjects.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00008

Please use custom response objects for your OK result. Background to keep your API as open as possible. If you use types like 'string' or
IEnumerable<T> you are not able to extend your API in the future without breaking changes.

Findings {wrongResponseObjects.Count}': 

{wrongResponseObjects.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }


}
